mapper.select:
SELECT p.post_id, category.name AS category_name, p.title, p.summary, CASE WHEN u.status = 'DELETED' THEN '탈퇴한 사용자' ELSE u.nickname END AS author_nickname, (SELECT pi.storage_key FROM post_images pi WHERE pi.post_id = p.post_id ORDER BY pi.display_order, pi.image_id LIMIT 1) AS storage_key, rr.distance_km, rr.duration_seconds, (SELECT COUNT(*) FROM post_likes pl WHERE pl.post_id = p.post_id) AS like_count, (SELECT COUNT(*) FROM comments c WHERE c.post_id = p.post_id AND c.deleted_at IS NULL AND c.status = 'PUBLISHED' AND ( c.parent_comment_id IS NULL OR EXISTS ( SELECT 1 FROM comments live_parent JOIN users live_parent_author ON live_parent_author.user_id = live_parent.author_id WHERE live_parent.comment_id = c.parent_comment_id AND live_parent.deleted_at IS NULL AND live_parent.status = 'PUBLISHED' AND live_parent_author.status <> 'SUSPENDED' ) ) AND NOT EXISTS ( SELECT 1 FROM users hidden_author WHERE hidden_author.user_id = c.author_id AND hidden_author.status = 'SUSPENDED' )) AS comment_count, p.author_id FROM posts p JOIN users u ON u.user_id = p.author_id LEFT JOIN categories category ON category.category_id = p.category_id LEFT JOIN running_records rr ON rr.post_id = p.post_id WHERE p.status = 'PUBLISHED' AND p.deleted_at IS NULL AND u.status <> 'SUSPENDED' ORDER BY
p.published_at ASC, p.post_id ASC p.view_count DESC, p.published_at DESC, p.post_id DESC like_count DESC, p.published_at DESC, p.post_id DESC p.published_at DESC, p.post_id DESC
LIMIT #{limit} OFFSET #{offset}
